import * as P from './planner.js';
import {sendNotice} from './school-life.js';

export const EVENTS=[
 {id:'rolling',name:'공 굴리기',icon:'circle',equipment:'부드러운 공',scene:'공이 옆으로 굴러가자 친구들이 기다려 줍니다.',question:'천천히 해도 괜찮죠?',choices:['서두르지 않고 자신의 차례로 해 보기','친구와 짝을 지어 함께 해 보기']},
 {id:'beanbag',name:'콩주머니 표적 넣기',icon:'target',equipment:'콩주머니·표적판',scene:'표적을 바라보는 학생이 참여 거리를 바꾸고 싶다고 말합니다.',question:'조금 가까운 곳에서 해 봐도 돼요?',choices:['서로 다른 출발선을 함께 정하기','연습 한 번 후 편한 거리 고르기']},
 {id:'basket',name:'바구니 공 넣기',icon:'dribbble',equipment:'부드러운 공·바구니',scene:'골인보다 차례를 지키고 응원하는 목소리가 커집니다.',question:'한 번 더 해 보는 친구를 응원해도 돼요?',choices:['노력한 장면을 찾아 응원하기','기록하는 친구와 차례를 확인하기']},
 {id:'relay',name:'이어달리기',icon:'flag',equipment:'학교 제공 바통',scene:'다음 차례를 기다리던 학생이 순서를 다시 확인합니다.',question:'제 차례를 친구가 알려 줘도 돼요?',choices:['모두가 볼 수 있게 순서 확인하기','예비 선수와 응원 역할도 함께 확인하기']},
 {id:'run',name:'짧은 거리 달리기',icon:'footprints',equipment:'학교 제공 표지',scene:'출발선에서 한 학생이 기록보다 끝까지 해 보고 싶다고 말합니다.',question:'제 속도로 끝까지 해 볼게요.',choices:['각자 세운 목표를 존중하기','끝난 뒤 서로의 노력을 말해 주기']},
 {id:'shuttle',name:'왕복 달리기',icon:'route',equipment:'표지·넓은 활동 공간',scene:'돌아오는 친구를 기다리며 학생들이 차례를 살핍니다.',question:'먼저 끝난 다음에는 무엇을 할까요?',choices:['정한 자리에서 다음 친구 응원하기','기록 역할과 함께 순서 확인하기']},
 {id:'bigball',name:'큰 공 함께 옮기기',icon:'circle-dot',equipment:'가벼운 큰 공',scene:'학생들이 서로 다른 속도를 맞추려고 이야기를 나눕니다.',question:'같이 구호를 정하면 쉬울 것 같아요.',choices:['서로 편한 구호를 함께 정하기','잠시 멈춰 역할과 속도 맞추기']},
 {id:'pair',name:'짝 협동 걷기',icon:'users-round',equipment:'표지·활동 공간',scene:'짝과 걷는 학생들이 보폭을 맞추는 방법을 찾습니다.',question:'친구 속도에 맞춰 천천히 갈래요.',choices:['상대의 속도를 먼저 물어보기','중간에 역할을 바꾸어 경험하기']},
 {id:'cloth',name:'협동 천 놀이',icon:'waves',equipment:'학교 제공 협동 천',scene:'친구들의 신호를 살피며 천을 함께 움직입니다.',question:'시작 신호를 다 같이 정할까요?',choices:['모두 이해하는 신호로 시작하기','참여하기 편한 위치 함께 고르기']},
 {id:'expression',name:'단체 표현과 응원',icon:'music',equipment:'음원·응원판',scene:'앞에 서기 어려운 학생이 응원판을 들고 싶다고 말합니다.',question:'춤 대신 응원판 역할을 해도 돼요?',choices:['표현과 안내 중 원하는 역할 고르기','여러 역할을 번갈아 경험하기']}
];
export const find=id=>EVENTS.find(e=>e.id===id);
const hash=text=>{let n=2166136261;for(const c of String(text))n=Math.imul(n^c.codePointAt(0),16777619);return n>>>0;};
export const data=s=>s.sportsDay||null;
export const willing=(s,id,studentId)=>hash(s.config.seed+id+studentId)%5!==0;
export const quota=s=>s.students.length<8?1:2;
export const rainy=day=>day%7===3;
export const defaultDay=s=>Math.min(M.demoDays(s)-1,Math.max(44,s.day+1));
const live=p=>p&&!['completed','cancelled'].includes(p.stage);
function officeError(s){if(M.movementBusy(s)||s.classLocation!=='classroom')return '학급 활동을 마치고 교실에서 계획을 확인해 주세요.';if(!['morning','break','afternoon','specialist'].includes(M.currentSlot(s).kind))return '수업 외 시간이나 전담수업 시간에 학교와 협의해 주세요.';return null;}
function calendar(s){const p=data(s);P.upsert(s,{id:p.id,title:'운동회 · 우리 반 참여',day:p.day,start:540,end:730,room:p.venue,type:'event',required:true,response:'참석',source:'학교 운동회 계획',status:p.stage==='completed'?'완료':p.stage==='cancelled'?'취소':'예정',note:p.note||''});}
function guardianNotice(s,title){const p=data(s);sendNotice(s,title,`${M.dateLabel({day:p.day})} 09:00–12:10 · ${M.ROOMS[p.venue].name}. 종목: ${p.events.map(e=>find(e.id).name).join(', ')}. 학교 공동 물품을 사용하며 모든 학생의 참여 역할을 함께 준비합니다.`,s.students.map(st=>st.parentId),false);}
function message(s,text){M.addMessage(s,'all','김지완 전담교사',text,{senderId:'specialist'});}
export function create(s,day,eventIds){const error=officeError(s);if(error)return {error};if(data(s))return {error:'이번 학년도 운동회 계획은 이미 있습니다. 기존 행사에서 날짜를 조정해 주세요.'};if(!Number.isInteger(day)||day<=s.day||day>=M.demoDays(s)||new Set(eventIds).size!==3||eventIds.some(id=>!find(id)))return {error:'앞으로의 날짜와 종목 3개를 선택해 주세요.'};
 s.sportsDay={id:'sports-2030-'+s.config.region,year:2030,day,stage:'planning',venue:'playground',events:eventIds.map(id=>({id,main:[],reserve:null})),practice:[],rounds:[],participants:[],changes:[],notified:false,note:'',created:M.stamp(s)};calendar(s);message(s,`${M.dateLabel({day})} 09:00–12:10 운동회 계획을 공유합니다. 우리 반 희망 종목 3개, 대표와 예비 선수, 모든 학생의 역할을 함께 준비해 주세요.`);M.log(s,'학년도 운동회 계획 접수');return {ok:true};}
export function assign(s,id,main,reserve){const p=data(s),event=p?.events.find(e=>e.id===id);if(!event||!['planning','ready'].includes(p.stage))return {error:'준비 중인 운동회에서 대표를 정해 주세요.'};if(!main.length||main.length>quota(s)||new Set(main).size!==main.length||main.some(id=>!s.students.some(st=>st.id===id)||!willing(s,event.id,id))||reserve&&(main.includes(reserve)||!s.students.some(st=>st.id===reserve)||!willing(s,event.id,reserve)))return {error:'참여 희망 학생 중 대표와 겹치지 않는 예비 선수를 골라 주세요.'};event.main=[...main];event.reserve=reserve||null;p.stage='planning';p.notified=false;M.log(s,find(id).name+' 대표·예비 선수와 학생 의견 확인');return {ok:true};}
export function practice(s,id){const p=data(s),event=p?.events.find(e=>e.id===id),slot=M.currentSlot(s);if(!event||!['planning','ready'].includes(p.stage)||s.day>=p.day)return {error:'운동회 전에 연습할 종목을 확인해 주세요.'};if(s.classLocation!==s.room||M.movementBusy(s)||!['classroom','gym','playground'].includes(s.room))return {error:'학급이 함께 있는 공간에서 연습해 주세요.'};if(!['morning','break'].includes(slot.kind)&&!(slot.kind==='lesson'&&['체육','창체','즐거운생활'].includes(slot.subject)))return {error:'아침·쉬는 시간 또는 체육·창체·즐거운생활 시간에 연습할 수 있어요.'};if(s.minute+5>slot.end)return {error:'다음 수업을 지킬 수 있도록 5분 이상 남았을 때 진행해 주세요.'};if(p.practice.some(r=>r.id===id&&r.day===s.day))return {error:'오늘 이 종목의 연습과 관찰은 기록했어요.'};const students=M.remainingStudents(s);if(!students.length)return {error:'함께 참여할 학생이 없어요.'};const r={id,day:s.day,date:M.stamp(s),students:students.map(st=>st.id),text:'희망 역할, 차례 확인과 친구에게 도움을 요청하는 모습을 함께 관찰함.'};p.practice.push(r);M.advance(s,5);M.log(s,find(id).name+' 연습과 참여 희망 관찰');return {ok:true};}
export function confirm(s){const p=data(s),error=officeError(s);if(error)return {error};if(!p||p.stage!=='planning')return {error:'준비 중인 계획을 확인해 주세요.'};if(p.events.some(e=>!e.main.length||!p.practice.some(r=>r.id===e.id)))return {error:'종목별 연습 관찰과 대표 선정을 마친 뒤 안내해 주세요.'};p.stage='ready';p.notified=true;calendar(s);guardianNotice(s,'우리 반 운동회 참여 안내');message(s,`${M.dateLabel({day:p.day})} ${M.ROOMS[p.venue].name} 운동회 참여 계획을 확인했습니다. 대표 외 학생도 응원·차례 안내·기록·정리 역할로 참여합니다. 준비물은 학교 공동 물품을 사용합니다.`);M.addNote(s,'teacher','운동회 참여 계획: '+p.events.map(e=>find(e.id).name).join(', ')+' · 참여 희망과 예비 선수 확인.');return {ok:true};}
export function change(s,day,venue,reason){const p=data(s),error=officeError(s);if(error)return {error};if(!live(p)||p.stage==='running'||!['playground','gym'].includes(venue)||!Number.isInteger(day)||day<s.day||day===s.day&&s.minute>=540||day>=M.demoDays(s)||!String(reason).trim())return {error:'행사 전, 가능한 날짜·장소와 변경 사유를 확인해 주세요.'};p.changes.push({fromDay:p.day,day,fromVenue:p.venue,venue,reason:String(reason).trim().slice(0,160),date:M.stamp(s)});p.day=day;p.venue=venue;calendar(s);if(p.notified)guardianNotice(s,'운동회 일정 변경 안내');message(s,`협의한 운동회 일정을 ${M.dateLabel({day})} 09:00 ${M.ROOMS[venue].name}(으)로 조정했습니다. 사유: ${String(reason).slice(0,160)}`);return {ok:true};}
export function cancel(s,reason){const p=data(s),error=officeError(s);if(error)return {error};if(!live(p)||p.stage==='running'||!String(reason).trim())return {error:'취소 사유를 입력해 주세요. 진행·완료된 행사는 취소할 수 없습니다.'};p.stage='cancelled';p.note=String(reason).slice(0,160);calendar(s);if(p.notified)sendNotice(s,'운동회 취소 안내',p.note+' 학교와 협의한 대체 활동은 따로 안내합니다.',s.students.map(st=>st.parentId),false);message(s,'운동회 계획을 취소로 기록했습니다. '+p.note+' 별도 대체 활동은 수업 계획에서 협의해 주세요.');return {ok:true};}
export function start(s){const p=data(s);if(p?.stage!=='ready'||s.day!==p.day||s.minute<540||s.minute>550||s.room!=='classroom'||s.classLocation!=='classroom'||M.movementBusy(s))return {error:'운동회 당일 09:00–09:10, 교실에서 출결을 확인하고 출발해 주세요.'};if(!s.attendanceConfirmed[s.day])return {error:'오늘의 출결을 먼저 확인해 주세요.'};if(p.venue==='playground'&&rainy(p.day))return {error:'학교에서 우천을 안내했습니다. 행사 전 체육관 또는 다른 날짜로 협의해 주세요.'};const students=s.students.filter(st=>M.isPresent(s,st.id));if(!students.length)return {error:'참여할 학생이 없어 시작할 수 없습니다. 일정을 조정해 주세요.'};if(!M.travelTogether(s,p.venue,'visit'))return {error:'먼저 현재 학급 활동을 마무리해 주세요.'};p.stage='running';p.participants=students.map(st=>st.id);p.started=M.stamp(s);calendar(s);return {ok:true};}
export function participation(s,index){const p=data(s),e=p?.events[index];if(!e)return null;const present=new Set(p.participants),main=e.main.filter(id=>present.has(id)),replaced=e.main.filter(id=>!present.has(id));if(replaced.length&&e.reserve&&present.has(e.reserve))main.push(e.reserve);return {main,reserve:e.reserve,replaced,roles:p.participants.map((id,i)=>({id,role:main.includes(id)?'종목 참여':['응원','차례 안내','활동 기록','물품 정리'][i%4]}))};}
export function step(s,choice,expectedRound=data(s)?.rounds.length){const p=data(s);if(p?.stage!=='running'||p.rounds.length!==expectedRound||p.rounds.length>=4||s.day!==p.day||s.room!==p.venue||![0,1].includes(choice))return {error:'진행 중인 운동회 활동을 확인해 주세요.'};const index=p.rounds.length,event=p.events[index],people=index<3?participation(s,index):{main:[],replaced:[],roles:p.participants.map(id=>({id,role:'함께 돌아보기'}))};const r={index,eventId:event?.id||'reflection',choice,roles:people.roles,main:people.main,replaced:people.replaced,date:M.stamp(s),text:index<3?find(event.id).choices[choice]:choice===0?'함께한 노력과 고마운 장면을 나눔':'다음에 바꾸고 싶은 참여 방법을 나눔'};p.rounds.push(r);for(const st of s.students)if(p.participants.includes(st.id)){M.remember(s,st,(event?find(event.id).name+' · ':'운동회 돌아보기 · ')+r.text,1);st.mood=M.clamp(st.mood+2);}s.unity=M.clamp(s.unity+2);M.advance(s,Math.max(0,[580,630,680,726][index]-s.minute));M.log(s,(event?find(event.id).name:'운동회 마무리')+' · '+r.text);
 if(p.rounds.length===4){p.stage='completed';p.completed=M.stamp(s);s.journey.activityDone=true;M.travelTogether(s,'classroom','return');calendar(s);M.addNote(s,'teacher',`운동회 참여 ${p.participants.length}명 · ${p.events.map(e=>find(e.id).name).join(', ')}. 모든 학생의 역할과 소감을 기록함.`);message(s,'우리 반 운동회 참여 기록과 마무리 확인을 받았습니다. 서로의 노력을 담은 소감을 다음 학년 협의에서 나누어요.');}return {ok:true,round:r};}

export function valid(raw){const p=raw.sportsDay;if(p===undefined||p===null)return true;const ids=knownIds(raw),idList=list=>Array.isArray(list)&&new Set(list).size===list.length&&list.every(id=>ids.has(id));if(!p||p.year!==2030||typeof p.id!=='string'||!['planning','ready','running','completed','cancelled'].includes(p.stage)||!Number.isInteger(p.day)||p.day<0||p.day>=M.demoDays(raw)||!['playground','gym'].includes(p.venue)||!Array.isArray(p.events)||p.events.length!==3||new Set(p.events.map(e=>e.id)).size!==3||p.events.some(e=>!find(e.id)||!idList(e.main)||e.main.length>2||e.reserve!==null&&(!ids.has(e.reserve)||e.main.includes(e.reserve)))||!Array.isArray(p.practice)||p.practice.some(r=>!find(r.id)||!Number.isInteger(r.day)||!idList(r.students))||!Array.isArray(p.changes)||!idList(p.participants)||!Array.isArray(p.rounds)||p.rounds.length>4||p.rounds.some((r,i)=>r.index!==i||!idList(r.main)||!idList(r.replaced)||!Array.isArray(r.roles)||r.roles.some(x=>!ids.has(x.id)||typeof x.role!=='string'))||p.stage==='completed'&&p.rounds.length!==4||p.stage==='running'&&(p.rounds.length>=4||!p.participants.length))return false;return true;}
